mapper.select:

SELECT (COUNT(*) > 0) AS cumple_regla
FROM matricula_grupo mg
         JOIN calendario c ON c.pk_cale_id_calendario = #{calendario}
WHERE mg.pk_matg_id_matricula_grupo = #{matriculaGrupo}
  AND mg.matg_fecha_matricula <= c.cale_fecha
  AND (
    mg.matg_fecha_retiro IS NULL
        OR mg.matg_fecha_retiro > c.cale_fecha
    )

SELECT c.cale_trabajado
FROM calendario c
WHERE c.pk_cale_id_calendario = #{calendario}

SELECT g.pk_grup_id_grupo
FROM grupo g
         INNER JOIN grado grad         ON grad.pk_grad_id_grado = g.fk_grup_id_grado
         INNER JOIN nivel_grado ng     ON ng.pk_nivel_grado_id  = grad.fk_grad_id_nivel_grado
         INNER JOIN jornada j          ON j.pk_jorn_id_jornada  = g.fk_grup_id_jornada
         INNER JOIN tipo_jornada tj    ON tj.pk_tijo_id_tipo_jornada = j.fk_jorn_id_tipo_jornada
         INNER JOIN unidad_educativa ue
                    ON ue.pk_uned_id_unidad_educativa = grad.fk_grad_id_unidad_educativa
WHERE ue.uned_rbd = #{rbd}
  AND g.grup_letra = #{letra}
  AND ng.pk_nivel_grado_id = #{nivelGrado}
  AND tj.pk_tijo_id_tipo_jornada = #{tipoJornada}

SELECT c.pk_cale_id_calendario
FROM calendario c
WHERE c.fk_cale_id_grupo = #{grupo}

SELECT ue.pk_uned_id_unidad_educativa
FROM unidad_educativa ue
WHERE ue.uned_rbd = #{rbd}

SELECT mue.pk_mued_id_matricula_unidad_educativa
FROM matricula_unidad_educativa mue
WHERE mue.fk_mued_id_parvulo = #{parvulo}
  AND mue.fk_mued_id_unidad_educativa = #{unidadEducativa}

SELECT mg.pk_matg_id_matricula_grupo
FROM matricula_grupo mg
WHERE mg.fk_matg_id_grupo = #{grupo}
  AND mg.fk_matg_id_matricula_ue = #{matriculaUe}

SELECT pk_grad_id_grado
FROM grado
WHERE fk_grad_id_unidad_educativa = #{unidadEducativa}
  AND fk_grad_id_nivel_grado = #{nivelGrado}
    LIMIT 1

SELECT pk_grup_id_grupo
FROM grupo
WHERE fk_grup_id_grado = #{grado}
  AND grup_letra = #{letra}
    LIMIT 1
